#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Almost: set up the Studio (Google Calendar → GitHub Actions → R2 → Worker → Frame).
# Run from anywhere:  scripts/setup-studio.sh

cd "$(dirname "$0")/.."
ENV_FILE=.env
TOTAL_STAGES=10
REPO=pwansell/almost
TABLET=10.11.99.1
TABLET_KEY=~/.ssh/id_ed25519_almost
wrangler() { (cd worker && npx --yes wrangler "$@"); }

banner "Almost: Studio setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Google Calendar: secret iCal address"
say "The Studio reads Events from your dedicated Almost calendar."
open_url "https://calendar.google.com/calendar/u/0/r/settings"
step "In the left column under 'Settings for my calendars', click your Almost calendar."
step "Scroll to 'Integrate calendar' and copy 'Secret address in iCal format'."
note "It ends in /basic.ics. Treat it like a password: anyone with it can read the calendar."
ask_secret ICAL_URL "Paste the secret iCal address:"
[[ "$ICAL_URL" == https://calendar.google.com/*.ics ]] || warn "That doesn't look like a Google secret iCal address; continuing anyway."
write_env ICAL_URL "$ICAL_URL"
set_secret ICAL_URL "$ICAL_URL"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Gemini key for GitHub Actions"
GEMINI_API_KEY=$(_existing GEMINI_API_KEY || true)
if [[ -z "$GEMINI_API_KEY" ]]; then
  open_url "https://aistudio.google.com/apikey"
  ask_secret GEMINI_API_KEY "Paste your Gemini API key:"
  write_env GEMINI_API_KEY "$GEMINI_API_KEY"
else
  say "Using the Gemini key already saved in .env."
fi
set_secret GEMINI_API_KEY "$GEMINI_API_KEY"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: log in"
say "Wrangler (Cloudflare's tool) will open your browser to log in."
note "No Cloudflare account yet? Use 'Sign up' on that page; the free plan is all Almost needs."
pause "Press Enter to open the login page"
(cd worker && npm install --silent >/dev/null 2>&1) || true
until wrangler login; do confirm "Login didn't finish. Try again?" || exit 1; done
R2_ACCOUNT_ID=$(wrangler whoami 2>/dev/null | grep -oE '[0-9a-f]{32}' | head -n1 || true)
if [[ -z "$R2_ACCOUNT_ID" ]]; then
  warn "Couldn't read your account ID automatically."
  step "In the Cloudflare dashboard, open 'Account home' → your account → copy 'Account ID'."
  ask R2_ACCOUNT_ID "Paste the Account ID:"
fi
write_env R2_ACCOUNT_ID "$R2_ACCOUNT_ID"
set_secret R2_ACCOUNT_ID "$R2_ACCOUNT_ID"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "R2: create the 'almost' bucket"
say "R2 is Cloudflare's file storage; the Studio keeps Artwork and Plates there."
until wrangler r2 bucket list 2>/dev/null | grep -qE '(^|[[:space:]])almost$' || wrangler r2 bucket create almost; do
  warn "R2 isn't enabled on this account yet."
  open_url "https://dash.cloudflare.com/$R2_ACCOUNT_ID/r2/overview"
  step "Click 'Purchase R2 Plan' / 'Enable R2' and follow the steps."
  note "Cloudflare may ask for a card even for the free tier; Almost's usage stays far inside it."
  pause "Press Enter once R2 is enabled"
done
printf '  %s✓%s bucket almost is ready\n' "$GREEN" "$RESET"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "R2: access key for GitHub Actions"
open_url "https://dash.cloudflare.com/$R2_ACCOUNT_ID/r2/api-tokens"
step "Click 'Create Account API token' (or 'Create API token')."
step "Name it 'almost-studio'. Permissions: 'Object Read & Write'."
step "Under 'Specify bucket(s)', choose 'Apply to specific buckets only' → almost."
step "Create it, then copy the 'Access Key ID' and 'Secret Access Key' (shown once)."
ask R2_ACCESS_KEY_ID "Paste the Access Key ID:"
ask_secret R2_SECRET_ACCESS_KEY "Paste the Secret Access Key:"
write_env R2_ACCESS_KEY_ID "$R2_ACCESS_KEY_ID"
write_env R2_SECRET_ACCESS_KEY "$R2_SECRET_ACCESS_KEY"
set_secret R2_ACCESS_KEY_ID "$R2_ACCESS_KEY_ID"
set_secret R2_SECRET_ACCESS_KEY "$R2_SECRET_ACCESS_KEY"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "GitHub: token so the Preview can start a render"
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: 'almost-preview'. Expiration: the longest you're comfortable with."
step "Repository access: 'Only select repositories' → $REPO."
step "Permissions → Repository permissions → Actions: 'Read and write'. Nothing else."
step "Generate the token and copy it."
note "When it expires, the Preview stops starting renders; the nightly render keeps working."
ask_secret GITHUB_DISPATCH_TOKEN "Paste the token:"
write_env GITHUB_DISPATCH_TOKEN "$GITHUB_DISPATCH_TOKEN"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Deploy the Worker"
FRAME_TOKEN=$(_existing FRAME_TOKEN || true)
PREVIEW_TOKEN=$(_existing PREVIEW_TOKEN || true)
[[ -n "$FRAME_TOKEN" ]] || FRAME_TOKEN=$(openssl rand -hex 24)
[[ -n "$PREVIEW_TOKEN" ]] || PREVIEW_TOKEN=$(openssl rand -hex 24)
write_env FRAME_TOKEN "$FRAME_TOKEN"
write_env PREVIEW_TOKEN "$PREVIEW_TOKEN"
say "This publishes the Worker at <name>.<your-subdomain>.workers.dev."
note "First time only, Wrangler may ask you to choose your workers.dev subdomain."
confirm "Deploy the Worker now?" || exit 1
deploy_log=$(mktemp)
wrangler deploy 2>&1 | tee "$deploy_log"
STUDIO_BASE_URL=$(grep -oE 'https://[a-z0-9.-]+\.workers\.dev' "$deploy_log" | head -n1 || true)
rm -f "$deploy_log"
[[ -n "$STUDIO_BASE_URL" ]] || ask STUDIO_BASE_URL "Paste the https://….workers.dev address it printed:"
write_env STUDIO_BASE_URL "$STUDIO_BASE_URL"
for s in FRAME_TOKEN PREVIEW_TOKEN; do printf '%s' "${!s}" | wrangler secret put "$s" >/dev/null; done
printf '%s' "$GITHUB_DISPATCH_TOKEN" | wrangler secret put GITHUB_TOKEN >/dev/null
printf '  %s✓%s Worker secrets set\n' "$GREEN" "$RESET"
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Art Library (optional)"
say "Generates the Default Artwork plus 21 themed pieces in the House Style,"
say "used when an Event's own Artwork can't be generated. About 22 images."
if confirm "Generate the Art Library now? (a few minutes)"; then
  (set -a; . ./.env; set +a; export R2_BUCKET=almost PYTHONWARNINGS=ignore
   cd studio && uv run -q python -m almost_studio make-library) || warn "Art Library stopped early; re-run this script to finish it."
else
  SKIPPED+=("Art Library: cd studio && uv run python -m almost_studio make-library (with .env loaded)")
fi
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "First render"
say "Starts the Studio workflow on GitHub and waits for it (about 1–2 minutes)."
if confirm "Run it now?"; then
  gh workflow run studio.yml --repo "$REPO" --ref main
  sleep 8
  run_id=$(gh run list --repo "$REPO" --workflow studio.yml -L1 --json databaseId -q '.[0].databaseId')
  if gh run watch "$run_id" --repo "$REPO" --exit-status; then
    printf '  %s✓%s Plates rendered\n' "$GREEN" "$RESET"
    open_url "$STUDIO_BASE_URL/preview/$PREVIEW_TOKEN"
    note "Bookmark that Preview page; it's private to whoever has the link."
  else
    warn "The render failed; see: gh run view $run_id --repo $REPO --log-failed"
  fi
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Point the Frame at the Studio"
printf 'STUDIO_URL=%s/frame/%s\n' "$STUDIO_BASE_URL" "$FRAME_TOKEN" > frame/frame.conf
printf '  %s✓ wrote%s frame/frame.conf\n' "$GREEN" "$RESET"
step "Connect the tablet by USB and press its power button so it's awake."
pause "Press Enter when it's awake"
if ssh -i "$TABLET_KEY" -o BatchMode=yes -o ConnectTimeout=6 root@"$TABLET" true 2>/dev/null; then
  frame/install.sh "$TABLET"
  scp -q -i "$TABLET_KEY" frame/frame.conf root@"$TABLET":/home/root/almost/frame.conf
  say "Test fetch from the tablet:"
  ssh -i "$TABLET_KEY" root@"$TABLET" '/home/root/almost/almost.sh fetch; tail -n 3 /home/root/almost/almost.log'
else
  SKIPPED+=("Frame: wake the tablet on USB, then run frame/install.sh and scp frame/frame.conf to /home/root/almost/")
  warn "Couldn't reach the tablet; finish this step later."
fi
pause

finish
